import React, { forwardRef, type ReactNode } from 'react';

import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { Flex } from '../../layouts-core/flex/Flex.js';

//#region Typings
/** Accepted properties for the Button Prefix */
export interface ButtonPrefixProps extends StylingProps, DataTestId {
  /** Elements to be displayed in the Button Prefix slot. */
  children: ReactNode;
}
//#endregion

/** Button Prefix component */
export const Prefix = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  ButtonPrefixProps
>((props, forwardedRef) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  }: ButtonPrefixProps = props;

  return (
    <Flex
      data-testid={dataTestId}
      ref={forwardedRef}
      gap={0}
      className={consumerClassName}
      style={consumerStyle}
    >
      {children}
    </Flex>
  );
});

(Prefix as typeof Prefix & { displayName: string }).displayName =
  'Button.Prefix';
